"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";
import {
  Vote,
  Send,
  Mic,
  MicOff,
  Volume2,
  VolumeX,
  ArrowLeft,
  Sparkles,
  ExternalLink,
  Loader2,
} from "lucide-react";
import type { ChatMessage } from "@/types";
import { generateId } from "@/lib/utils";

export default function ChatPage() {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: "welcome",
      role: "assistant",
      content:
        "Namaste! 🙏 I'm Matdaan Mitra, your election guide. Ask me anything about voter registration, polling process, your rights, or election phases. I'm here to help!",
      timestamp: Date.now(),
    },
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Get user profile from localStorage
  const [profile, setProfile] = useState<Record<string, string> | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem("matdaan-profile");
    if (saved) setProfile(JSON.parse(saved));
  }, []);

  // Auto-scroll on new messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Check for topic query param
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const topic = params.get("topic");
    if (topic) {
      const topicQuestions: Record<string, string> = {
        "pre-registration": "How can I pre-register to vote if I'm under 18?",
        "registration-documents": "What documents do I need to register as a voter?",
        "voter-rights": "What are my rights as a voter in India?",
        "voting-process": "How does voting work with EVM and VVPAT?",
        "polling-checklist": "What should I bring on polling day?",
        "how-to-vote": "Walk me through the voting process step by step.",
        "polling-hours": "What are the polling hours and what if I'm late?",
        "counting-process": "How does vote counting work in India?",
      };
      const question = topicQuestions[topic];
      if (question) {
        setTimeout(() => handleSend(question), 500);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSend = async (overrideMessage?: string) => {
    const msg = overrideMessage || input.trim();
    if (!msg || isLoading) return;

    const userMsg: ChatMessage = {
      id: generateId(),
      role: "user",
      content: msg,
      timestamp: Date.now(),
    };

    const assistantMsgId = generateId();

    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setIsLoading(true);

    try {
      const userContext = profile
        ? `Age: ${profile.age}, State: ${profile.state}, Status: ${profile.voterStatus}`
        : "Unknown";

      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: msg,
          userContext,
          language: profile?.preferredLanguage || "en",
        }),
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error || "Request failed");
      }

      // Create a placeholder assistant message
      setMessages((prev) => [
        ...prev,
        {
          id: assistantMsgId,
          role: "assistant",
          content: "",
          timestamp: Date.now(),
        },
      ]);
      setIsLoading(false);

      // Read the SSE stream
      const reader = res.body?.getReader();
      const decoder = new TextDecoder();

      if (!reader) throw new Error("No response body");

      let buffer = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Parse SSE lines
        const lines = buffer.split("\n\n");
        buffer = lines.pop() || "";

        for (const line of lines) {
          if (!line.startsWith("data: ")) continue;
          try {
            const data = JSON.parse(line.slice(6));

            if (data.content) {
              // Append streaming text
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === assistantMsgId
                    ? { ...m, content: m.content + data.content }
                    : m
                )
              );
            }

            if (data.done && data.citations) {
              // Attach citations at the end
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === assistantMsgId
                    ? { ...m, citations: data.citations }
                    : m
                )
              );
            }

            if (data.error) {
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === assistantMsgId
                    ? { ...m, content: data.error }
                    : m
                )
              );
            }
          } catch {
            // skip malformed chunks
          }
        }
      }
    } catch {
      setMessages((prev) => {
        // If placeholder exists, update it; otherwise add new
        const hasPlaceholder = prev.some((m) => m.id === assistantMsgId);
        if (hasPlaceholder) {
          return prev.map((m) =>
            m.id === assistantMsgId
              ? {
                  ...m,
                  content:
                    "Sorry, I'm having trouble connecting. Please make sure the Gemini API key is configured and try again.",
                }
              : m
          );
        }
        return [
          ...prev,
          {
            id: assistantMsgId,
            role: "assistant" as const,
            content:
              "Sorry, I'm having trouble connecting. Please make sure the Gemini API key is configured and try again.",
            timestamp: Date.now(),
          },
        ];
      });
    } finally {
      setIsLoading(false);
      inputRef.current?.focus();
    }
  };

  // Voice input
  const toggleVoice = () => {
    if (!("webkitSpeechRecognition" in window || "SpeechRecognition" in window)) {
      alert("Voice input is not supported in this browser. Try Chrome.");
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }


    const SpeechRecognitionAPI =
      (window as any).SpeechRecognition ||
      (window as any).webkitSpeechRecognition;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const recognition = new SpeechRecognitionAPI() as any;
    recognition.lang = profile?.preferredLanguage === "hi" ? "hi-IN" : profile?.preferredLanguage === "bn" ? "bn-IN" : "en-IN";
    recognition.continuous = false;
    recognition.interimResults = false;

    recognition.onstart = () => setIsListening(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      setIsListening(false);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognition.start();
  };

  // Text-to-speech
  const speakText = (text: string) => {
    if (isSpeaking) {
      window.speechSynthesis.cancel();
      setIsSpeaking(false);
      return;
    }

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = profile?.preferredLanguage === "hi" ? "hi-IN" : profile?.preferredLanguage === "bn" ? "bn-IN" : "en-IN";
    utterance.rate = 0.9;
    utterance.onend = () => setIsSpeaking(false);
    setIsSpeaking(true);
    window.speechSynthesis.speak(utterance);
  };

  const QUICK_QUESTIONS = [
    "How do I register to vote?",
    "What is NOTA?",
    "What do I need on polling day?",
    "Tell me about EVM & VVPAT",
  ];

  return (
    <div className="h-screen flex flex-col">
      {/* Header */}
      <header className="border-b border-border px-4 py-3 flex items-center gap-3 flex-shrink-0">
        <Link
          href="/dashboard"
          className="p-2 rounded-lg hover:bg-surface transition-colors"
          aria-label="Back to dashboard"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-orange-500 to-amber-400 flex items-center justify-center">
            <Vote className="w-4 h-4 text-gray-900" />
          </div>
          <div>
            <div className="font-semibold text-sm">Matdaan Mitra</div>
            <div className="text-xs text-muted-foreground flex items-center gap-1">
              <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
              AI Assistant
            </div>
          </div>
        </div>
      </header>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"} slide-in-up`}
          >
            <div
              className={`max-w-[85%] sm:max-w-[70%] rounded-2xl px-4 py-3 ${
                msg.role === "user"
                  ? "bg-gradient-to-r from-orange-500 to-amber-500 text-gray-900"
                  : "glass"
              }`}
            >
              {msg.role === "assistant" && (
                <div className="flex items-center gap-1.5 mb-1">
                  <Sparkles className="w-3.5 h-3.5 text-orange-400" />
                  <span className="text-xs font-medium text-orange-400">Matdaan Mitra</span>
                </div>
              )}
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.content}</p>

              {/* Citations */}
              {msg.citations && msg.citations.length > 0 && (
                <div className="mt-2 pt-2 border-t border-border/50">
                  <div className="text-xs text-muted-foreground flex items-center gap-1 flex-wrap">
                    <span>Sources:</span>
                    {msg.citations.map((c, i) => (
                      <a
                        key={i}
                        href={c}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-cyan-400 hover:underline inline-flex items-center gap-0.5"
                      >
                        {new URL(c).hostname}
                        <ExternalLink className="w-2.5 h-2.5" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {/* TTS button for assistant messages */}
              {msg.role === "assistant" && msg.id !== "welcome" && (
                <button
                  onClick={() => speakText(msg.content)}
                  className="mt-2 text-xs text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1"
                  aria-label={isSpeaking ? "Stop speaking" : "Read aloud"}
                >
                  {isSpeaking ? (
                    <VolumeX className="w-3.5 h-3.5" />
                  ) : (
                    <Volume2 className="w-3.5 h-3.5" />
                  )}
                  {isSpeaking ? "Stop" : "Listen"}
                </button>
              )}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start slide-in-up">
            <div className="glass rounded-2xl px-4 py-3 flex items-center gap-2">
              <Loader2 className="w-4 h-4 text-orange-400 animate-spin" />
              <span className="text-sm text-muted-foreground">Thinking...</span>
            </div>
          </div>
        )}

        {/* Quick questions (show only if no messages beyond welcome) */}
        {messages.length === 1 && (
          <div className="flex flex-wrap gap-2 mt-4">
            {QUICK_QUESTIONS.map((q) => (
              <button
                key={q}
                onClick={() => handleSend(q)}
                className="text-sm px-4 py-2 rounded-full glass hover:border-orange-500/30 transition-all"
              >
                {q}
              </button>
            ))}
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="border-t border-border p-4 flex-shrink-0">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleSend();
          }}
          className="flex items-center gap-2 max-w-3xl mx-auto"
        >
          <button
            type="button"
            onClick={toggleVoice}
            className={`p-3 rounded-xl transition-all ${
              isListening
                ? "bg-red-500/20 text-red-400 pulse-glow"
                : "hover:bg-surface text-muted-foreground hover:text-foreground"
            }`}
            aria-label={isListening ? "Stop listening" : "Start voice input"}
          >
            {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
          </button>

          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={isListening ? "Listening..." : "Ask about elections..."}
            className="flex-1 px-4 py-3 rounded-xl bg-surface border border-border text-foreground placeholder:text-muted-foreground focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-colors outline-none"
            disabled={isLoading}
            aria-label="Type your message"
          />

          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className="p-3 rounded-xl bg-gradient-to-r from-orange-500 to-amber-500 text-gray-900 disabled:opacity-30 transition-all hover:shadow-lg hover:shadow-orange-500/20"
            aria-label="Send message"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>

        <p className="text-center text-xs text-muted-foreground mt-2">
          Matdaan Mitra uses only verified ECI sources.{" "}
          <a href="https://eci.gov.in" target="_blank" rel="noopener noreferrer" className="text-cyan-400 hover:underline">
            eci.gov.in
          </a>
        </p>
      </div>
    </div>
  );
}

