"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  Vote,
  MessageCircle,
  Brain,
  Shield,
  MapPin,
  Mic,
  Settings,
  ExternalLink,
  Calendar,
  ChevronRight,
  LogOut,
  Sparkles,
  AlertTriangle,
  UserPlus,
  FileText,
  Scale,
  Search,
  ClipboardCheck,
  Clock,
  Phone,
  BarChart3,
  Trophy,
  BookOpen,
  HelpCircle,
  CheckCircle,
} from "lucide-react";
import type { UserProfile, ElectionPhase, ActionCard } from "@/types";
import { getActions, getPhaseInfo } from "@/lib/decisionEngine";

const ICON_MAP: Record<string, React.ElementType> = {
  sparkles: Sparkles,
  "book-open": BookOpen,
  "shield-check": Shield,
  "alert-triangle": AlertTriangle,
  "user-plus": UserPlus,
  "file-text": FileText,
  scale: Scale,
  search: Search,
  "map-pin": MapPin,
  calendar: Calendar,
  vote: Vote,
  "clipboard-check": ClipboardCheck,
  "check-circle": CheckCircle,
  clock: Clock,
  phone: Phone,
  "bar-chart": BarChart3,
  trophy: Trophy,
  "help-circle": HelpCircle,
  brain: Brain,
};

const PHASE_ORDER: ElectionPhase[] = [
  "announced",
  "nomination",
  "campaigning",
  "silence_period",
  "polling_day",
  "counting",
];

const SIDEBAR_LINKS = [
  { href: "/chat", icon: MessageCircle, label: "Chat Assistant" },
  { href: "/quiz", icon: Brain, label: "Election Quiz" },
  { href: "/myths", icon: Shield, label: "Myth Buster" },
  { href: "/locator", icon: MapPin, label: "Find Polling Station" },
];

export default function DashboardPage() {
  const router = useRouter();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [phase] = useState<ElectionPhase>("no_election");
  const [actions, setActions] = useState<ActionCard[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem("matdaan-profile");
    if (!saved) {
      router.push("/onboarding");
      return;
    }
    const parsed = JSON.parse(saved) as UserProfile;
    setProfile(parsed);
    setActions(getActions(parsed, phase));

    // Apply high-contrast theme if saved
    const hc = localStorage.getItem("matdaan-high-contrast");
    if (hc === "true") {
      document.documentElement.setAttribute("data-theme", "high-contrast");
    }
  }, [router, phase]);

  if (!profile) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-orange-500/30 border-t-orange-500 rounded-full animate-spin" />
      </div>
    );
  }

  const phaseInfo = getPhaseInfo(phase);
  const greeting = profile.age < 18
    ? `Welcome, Future Voter! 🌟`
    : profile.voterStatus === "registered"
    ? `Welcome back, Voter! 🗳️`
    : `Welcome! Let's get you registered ✨`;

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="border-b border-border px-6 py-3">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <Link href="/" className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-orange-500 to-amber-400 flex items-center justify-center">
              <Vote className="w-4 h-4 text-gray-900" />
            </div>
            <span className="font-display font-bold">Matdaan Mitra</span>
          </Link>
          <div className="flex items-center gap-3">
            <button
              className="p-2 rounded-lg hover:bg-surface transition-colors"
              aria-label="Voice mode"
            >
              <Mic className="w-5 h-5 text-muted-foreground" />
            </button>
            <Link
              href="/settings"
              className="p-2 rounded-lg hover:bg-surface transition-colors"
              aria-label="Settings"
            >
              <Settings className="w-5 h-5 text-muted-foreground" />
            </Link>
            <button
              onClick={() => {
                localStorage.removeItem("matdaan-profile");
                router.push("/");
              }}
              className="p-2 rounded-lg hover:bg-surface transition-colors"
              aria-label="Log out"
            >
              <LogOut className="w-5 h-5 text-muted-foreground" />
            </button>
          </div>
        </div>
      </header>

      <div className="flex-1 flex">
        {/* Sidebar */}
        <aside className="hidden lg:flex flex-col w-64 border-r border-border p-4 gap-2">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider px-3 mb-2">
            Quick Links
          </div>
          {SIDEBAR_LINKS.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm hover:bg-surface-hover transition-colors group"
            >
              <link.icon className="w-5 h-5 text-muted-foreground group-hover:text-orange-400 transition-colors" />
              <span>{link.label}</span>
            </Link>
          ))}

          <div className="mt-auto glass p-4 text-sm">
            <div className="text-muted-foreground text-xs mb-1">Your Profile</div>
            <div className="font-medium">{profile.state}</div>
            <div className="text-muted-foreground">
              Age {profile.age} · {profile.voterStatus.replace(/_/g, " ")}
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main id="main-content" className="flex-1 overflow-y-auto p-6 lg:p-8">
          <div className="max-w-4xl mx-auto">
            {/* Greeting */}
            <div className="mb-8">
              <h1 className="font-display text-3xl font-bold mb-2">{greeting}</h1>
              <p className="text-muted-foreground">
                Here&#39;s your personalized election guide based on your profile.
              </p>
            </div>

            {/* Election Phase Banner */}
            <div className="glass p-6 mb-8 relative overflow-hidden">
              <div className="absolute inset-0 bg-gradient-to-r from-orange-500/5 to-cyan-500/5 pointer-events-none" />
              <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${phase === "polling_day" ? "bg-red-500 pulse-glow" : phase === "no_election" ? "bg-green-500" : "bg-orange-500 pulse-glow"}`} />
                  <span className="text-sm font-medium text-muted-foreground">Current Phase</span>
                </div>
                <h2 className="font-display text-xl font-bold mb-1">{phaseInfo.label}</h2>
                <p className="text-muted-foreground text-sm">{phaseInfo.description}</p>
              </div>
            </div>

            {/* Timeline */}
            <div className="mb-10 overflow-x-auto pb-4">
              <div className="flex min-w-[600px]">
                {PHASE_ORDER.map((p, i) => {
                  const info = getPhaseInfo(p);
                  const isActive = p === phase;
                  const isPast = PHASE_ORDER.indexOf(phase) > i;
                  return (
                    <div key={p} className={`timeline-step ${isActive ? "active" : ""}`}>
                      <div
                        className={`timeline-dot ${
                          isActive
                            ? "!bg-orange-500 !border-orange-500"
                            : isPast
                            ? "!bg-green-600 !border-green-600"
                            : ""
                        }`}
                      >
                        <span className="text-xs font-bold">{i + 1}</span>
                      </div>
                      <span
                        className={`text-xs mt-2 text-center max-w-[80px] ${
                          isActive ? "text-orange-400 font-semibold" : "text-muted-foreground"
                        }`}
                      >
                        {info.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Action Cards */}
            <div className="mb-6">
              <h2 className="font-display text-xl font-bold mb-4 flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-orange-400" />
