                      </div>
                    </div>
                    <div className="mt-auto pt-3">
                      {action.cta.type === "external" ? (
                        <a
                          href={action.cta.href}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1.5 text-sm font-medium text-orange-400 hover:text-orange-300 transition-colors"
                        >
                          {action.cta.label}
                          <ExternalLink className="w-3.5 h-3.5" />
                        </a>
                      ) : (
                        <Link
                          href={action.cta.href}
                          className="inline-flex items-center gap-1.5 text-sm font-medium text-orange-400 hover:text-orange-300 transition-colors"
                        >
                          {action.cta.label}
                          <ChevronRight className="w-3.5 h-3.5" />
                        </Link>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Mobile Quick Links */}
            <div className="lg:hidden glass p-4 mb-8">
              <h3 className="font-semibold mb-3 text-sm">Quick Links</h3>
              <div className="grid grid-cols-2 gap-2">
                {SIDEBAR_LINKS.map((link) => (
                  <Link
                    key={link.href}
                    href={link.href}
                    className="flex items-center gap-2 p-3 rounded-xl bg-surface hover:bg-surface-hover transition-colors text-sm"
                  >
                    <link.icon className="w-4 h-4 text-orange-400" />
                    {link.label}
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

