"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  MapPin,
  Navigation,
  Phone,
  ExternalLink,
  Loader2,
  AlertCircle,
  Search,
} from "lucide-react";

export default function LocatorPage() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [location, setLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const mapRef = useRef<HTMLDivElement>(null);

  // Check if Maps API is available
  const mapsApiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;

  const getLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setError("Geolocation is not supported by your browser.");
      return;
    }

    setLoading(true);
    setError(null);

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
        setLoading(false);
      },
      (err) => {
        setError(
          err.code === 1
            ? "Location access denied. Please enable location services."
            : "Unable to get your location. Please try again."
        );
        setLoading(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  useEffect(() => {
    // Auto-request location on mount
    getLocation();
  }, [getLocation]);

  const openGoogleMaps = () => {
    if (location) {
      window.open(
        `https://www.google.com/maps/search/polling+station/@${location.lat},${location.lng},15z`,
        "_blank"
      );
    }
  };

  const searchLocation = () => {
    if (searchQuery.trim()) {
      window.open(
        `https://www.google.com/maps/search/polling+station+${encodeURIComponent(searchQuery)}`,
        "_blank"
      );
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="border-b border-border px-4 py-3 flex items-center gap-3">
        <Link href="/dashboard" className="p-2 rounded-lg hover:bg-surface transition-colors" aria-label="Back">
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div className="flex items-center gap-2">
          <MapPin className="w-5 h-5 text-violet-400" />
          <span className="font-semibold">Polling Station Locator</span>
        </div>
      </header>

      <main id="main-content" className="flex-1 p-6">
        <div className="max-w-3xl mx-auto">
          {/* Header */}
          <div className="text-center mb-8">
            <h1 className="font-display text-3xl font-bold mb-2">
              Find Your <span className="gradient-text">Polling Station</span>
            </h1>
            <p className="text-muted-foreground">
              Locate your designated polling booth and get directions.
            </p>
          </div>

          {/* Search by location name */}
          <div className="glass p-4 mb-6">
            <label className="block text-sm font-medium mb-2">Search by area name</label>
            <div className="flex gap-2">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Enter your area, pincode, or constituency..."
                className="flex-1 px-4 py-2.5 rounded-xl bg-surface border border-border text-sm focus:border-orange-500 outline-none"
                onKeyDown={(e) => e.key === "Enter" && searchLocation()}
                aria-label="Search location"
              />
              <button
                onClick={searchLocation}
                disabled={!searchQuery.trim()}
                className="px-4 py-2.5 rounded-xl bg-gradient-to-r from-orange-500 to-amber-500 text-gray-900 text-sm font-medium disabled:opacity-30"
              >
                <Search className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Map area */}
          <div className="glass overflow-hidden mb-6">
            <div
              ref={mapRef}
              className="h-[400px] bg-surface flex items-center justify-center relative"
            >
              {loading ? (
                <div className="text-center">
                  <Loader2 className="w-8 h-8 text-orange-400 animate-spin mx-auto mb-3" />
                  <p className="text-muted-foreground text-sm">Getting your location...</p>
                </div>
              ) : error ? (
                <div className="text-center px-6">
                  <AlertCircle className="w-8 h-8 text-red-400 mx-auto mb-3" />
                  <p className="text-red-400 text-sm mb-3">{error}</p>
                  <button onClick={getLocation} className="btn-secondary text-sm">
                    Try Again
                  </button>
                </div>
              ) : location ? (
                <div className="text-center">
                  {mapsApiKey ? (
                    <iframe
                      title="Polling Station Map"
                      width="100%"
                      height="400"
                      style={{ border: 0 }}
                      loading="lazy"
                      src={`https://www.google.com/maps/embed/v1/search?key=${mapsApiKey}&q=polling+station&center=${location.lat},${location.lng}&zoom=14`}
                    />
                  ) : (
                    <>
                      <MapPin className="w-10 h-10 text-orange-400 mx-auto mb-3" />
                      <p className="text-sm text-muted-foreground mb-1">
                        Location: {location.lat.toFixed(4)}°N, {location.lng.toFixed(4)}°E
                      </p>
                      <p className="text-xs text-muted-foreground mb-4">
                        Configure Google Maps API key for embedded map view
                      </p>
                      <button
                        onClick={openGoogleMaps}
                        className="btn-primary text-sm"
                      >
                        <Navigation className="w-4 h-4" />
                        Open in Google Maps
                      </button>
                    </>
                  )}
                </div>
              ) : (
                <div className="text-center">
                  <MapPin className="w-8 h-8 text-muted-foreground mx-auto mb-3" />
                  <p className="text-muted-foreground text-sm">
                    Enable location to find nearby polling stations.
                  </p>
                  <button onClick={getLocation} className="btn-primary text-sm mt-3">
                    <Navigation className="w-4 h-4" />
                    Use My Location
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Info cards */}
          <div className="grid sm:grid-cols-2 gap-4 mb-6">
            <div className="glass p-4">
              <h3 className="font-semibold text-sm mb-2 flex items-center gap-2">
                <Phone className="w-4 h-4 text-cyan-400" />
                ECI Voter Helpline
              </h3>
              <p className="text-muted-foreground text-sm mb-2">
                Call <strong className="text-foreground">1950</strong> (toll-free) to find your exact polling station.
              </p>
              <a
                href="tel:1950"
                className="text-sm text-cyan-400 hover:underline inline-flex items-center gap-1"
              >
                Call Now <ExternalLink className="w-3 h-3" />
              </a>
            </div>

            <div className="glass p-4">
              <h3 className="font-semibold text-sm mb-2 flex items-center gap-2">
                <MapPin className="w-4 h-4 text-violet-400" />
                Official Voter Portal
              </h3>
              <p className="text-muted-foreground text-sm mb-2">
                Check your booth details on the official ECI Voter Portal.
              </p>
              <a
                href="https://voterportal.eci.gov.in/"
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-cyan-400 hover:underline inline-flex items-center gap-1"
              >
                Visit Portal <ExternalLink className="w-3 h-3" />
              </a>
            </div>
          </div>

          {/* Tips */}
          <div className="glass p-4">
            <h3 className="font-semibold text-sm mb-3">🗳️ Polling Day Tips</h3>
            <ul className="space-y-2 text-sm text-muted-foreground">
              <li className="flex items-start gap-2">
                <span className="text-orange-400">•</span>
                You can ONLY vote at your assigned polling station — not at any other.
              </li>
              <li className="flex items-start gap-2">
                <span className="text-orange-400">•</span>
                Carry your Voter ID (EPIC) or any approved photo ID.
              </li>
              <li className="flex items-start gap-2">
                <span className="text-orange-400">•</span>
                Arrive early to avoid long queues. Polling usually starts at 7 AM.
              </li>
              <li className="flex items-start gap-2">
                <span className="text-orange-400">•</span>
                If you&#39;re in the queue by closing time (6 PM), you will be allowed to vote.
              </li>
            </ul>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  Shield,
  XCircle,
  CheckCircle,
  ChevronDown,
  Search,
  ExternalLink,
  Send,
  Loader2,
} from "lucide-react";
import mythsData from "@/data/myths.json";
import type { MythFact } from "@/types";

const myths = mythsData as MythFact[];
const categories = [...new Set(myths.map((m) => m.category))];

export default function MythsPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSubmit, setShowSubmit] = useState(false);
  const [submitMyth, setSubmitMyth] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const filteredMyths = myths.filter((m) => {
    const matchesSearch =
      !searchQuery ||
      m.myth.toLowerCase().includes(searchQuery.toLowerCase()) ||
      m.fact.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = !selectedCategory || m.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const handleSubmitMyth = () => {
    if (!submitMyth.trim()) return;
    // In production, save to Firestore for review
    console.log("Submitted myth for review:", submitMyth);
    setSubmitted(true);
    setSubmitMyth("");
    setTimeout(() => {
      setSubmitted(false);
      setShowSubmit(false);
    }, 3000);
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="border-b border-border px-4 py-3 flex items-center gap-3">
        <Link href="/dashboard" className="p-2 rounded-lg hover:bg-surface transition-colors" aria-label="Back">
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div className="flex items-center gap-2">
          <Shield className="w-5 h-5 text-emerald-400" />
          <span className="font-semibold">Myth vs Fact</span>
        </div>
      </header>

      <main id="main-content" className="flex-1 p-6">
        <div className="max-w-3xl mx-auto">
          {/* Intro */}
          <div className="text-center mb-8">
            <h1 className="font-display text-3xl font-bold mb-2">
              Don&#39;t Fall for <span className="gradient-text">Election Myths</span>
            </h1>
            <p className="text-muted-foreground">
              Tap any claim to reveal the verified fact behind it.
            </p>
          </div>

          {/* Search & Filter */}
          <div className="flex flex-col sm:flex-row gap-3 mb-6">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <input
                type="text"
                placeholder="Search myths..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-surface border border-border text-sm focus:border-orange-500 focus:ring-1 focus:ring-orange-500 outline-none transition-colors"
                aria-label="Search myths"
              />
            </div>
            <div className="flex gap-2 flex-wrap">
              <button
                onClick={() => setSelectedCategory(null)}
                className={`px-3 py-2 rounded-lg text-xs font-medium transition-all ${
                  !selectedCategory ? "bg-orange-500/20 text-orange-400 border border-orange-500/30" : "bg-surface text-muted-foreground border border-border hover:border-orange-500/20"
                }`}
              >
                All
              </button>
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(selectedCategory === cat ? null : cat)}
                  className={`px-3 py-2 rounded-lg text-xs font-medium transition-all ${
                    selectedCategory === cat
                      ? "bg-orange-500/20 text-orange-400 border border-orange-500/30"
                      : "bg-surface text-muted-foreground border border-border hover:border-orange-500/20"
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* Myths List */}
          <div className="space-y-3 mb-8">
            {filteredMyths.map((myth) => {
              const isExpanded = expandedId === myth.id;
              return (
                <button
                  key={myth.id}
                  onClick={() => setExpandedId(isExpanded ? null : myth.id)}
                  className="w-full glass text-left transition-all hover:border-orange-500/20"
                  aria-expanded={isExpanded}
                >
                  <div className="p-4">
                    {/* Myth (claim) */}
                    <div className="flex items-start gap-3">
                      <XCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <div className="text-xs font-semibold text-red-400 uppercase tracking-wider mb-1">
                          Myth
                        </div>
                        <p className="text-sm font-medium leading-relaxed">{myth.myth}</p>
                      </div>
                      <ChevronDown
                        className={`w-4 h-4 text-muted-foreground transition-transform ${
                          isExpanded ? "rotate-180" : ""
                        }`}
                      />
                    </div>

                    {/* Fact (revealed on expand) */}
                    {isExpanded && (
                      <div className="mt-4 pt-4 border-t border-border slide-in-up">
                        <div className="flex items-start gap-3">
                          <CheckCircle className="w-5 h-5 text-green-400 flex-shrink-0 mt-0.5" />
                          <div>
                            <div className="text-xs font-semibold text-green-400 uppercase tracking-wider mb-1">
                              Fact
                            </div>
                            <p className="text-sm text-muted-foreground leading-relaxed">
                              {myth.fact}
                            </p>
                            <p className="text-xs text-muted-foreground mt-2 flex items-center gap-1">
                              <ExternalLink className="w-3 h-3" />
                              Source: {myth.source}
                            </p>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </button>
              );
            })}

            {filteredMyths.length === 0 && (
              <div className="text-center py-12 text-muted-foreground">
                <Shield className="w-8 h-8 mx-auto mb-3 opacity-40" />
                <p>No myths match your search.</p>
              </div>
            )}
          </div>

          {/* Submit a Myth */}
          <div className="glass p-6">
            <button
              onClick={() => setShowSubmit(!showSubmit)}
              className="w-full flex items-center justify-between"
            >
              <div>
                <h3 className="font-semibold text-sm">Heard a myth?</h3>
                <p className="text-xs text-muted-foreground">Submit it for our team to fact-check.</p>
              </div>
              <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform ${showSubmit ? "rotate-180" : ""}`} />
            </button>

            {showSubmit && (
              <div className="mt-4 pt-4 border-t border-border slide-in-up">
                {submitted ? (
                  <div className="flex items-center gap-2 text-green-400 text-sm">
                    <CheckCircle className="w-4 h-4" />
                    Thank you! We&#39;ll review this.
                  </div>
                ) : (
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={submitMyth}
                      onChange={(e) => setSubmitMyth(e.target.value)}
                      placeholder="Describe the myth you heard..."
                      className="flex-1 px-4 py-2.5 rounded-xl bg-surface border border-border text-sm focus:border-orange-500 outline-none"
                      aria-label="Submit a myth"
                    />
                    <button
                      onClick={handleSubmitMyth}
                      disabled={!submitMyth.trim()}
                      className="p-2.5 rounded-xl bg-gradient-to-r from-orange-500 to-amber-500 text-gray-900 disabled:opacity-30"
                      aria-label="Submit"
                    >
                      <Send className="w-4 h-4" />
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import {
  Vote,
  ArrowLeft,
  Brain,
  CheckCircle,
  XCircle,
  ArrowRight,
  Trophy,
  RotateCcw,
  Loader2,
  Sparkles,
  Zap,
  Star,
} from "lucide-react";
import type { QuizQuestion } from "@/types";

type Difficulty = "beginner" | "intermediate" | "advanced";

const TOTAL_QUESTIONS = 5;

const DIFFICULTY_CONFIG: Record<Difficulty, { label: string; color: string; icon: React.ElementType }> = {
  beginner: { label: "Beginner", color: "text-green-400", icon: Star },
  intermediate: { label: "Intermediate", color: "text-yellow-400", icon: Zap },
  advanced: { label: "Advanced", color: "text-red-400", icon: Brain },
};

export default function QuizPage() {
  const [difficulty, setDifficulty] = useState<Difficulty | null>(null);
  const [currentQ, setCurrentQ] = useState(0);
  const [question, setQuestion] = useState<QuizQuestion | null>(null);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [score, setScore] = useState(0);
  const [loading, setLoading] = useState(false);
  const [quizComplete, setQuizComplete] = useState(false);
  const [answers, setAnswers] = useState<{ correct: boolean; question: string }[]>([]);

  const fetchQuestion = async (diff: Difficulty) => {
    setLoading(true);
    setSelectedAnswer(null);
    setShowExplanation(false);
    setQuestion(null);

    try {
      const profile = JSON.parse(localStorage.getItem("matdaan-profile") || "{}");
      const res = await fetch("/api/quiz/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          difficulty: diff,
          voterStatus: profile.voterStatus || "unknown",
        }),
      });
      const data = await res.json();
      setQuestion(data);
    } catch {
      setQuestion({
        question: "What does EVM stand for?",
        options: [
          "Electronic Voting Machine",
          "Electoral Verification Method",
          "Electronic Vote Monitor",
          "Election Validation Mechanism",
        ],
        correctIndex: 0,
        explanation: "EVM stands for Electronic Voting Machine, used in Indian elections since 2004.",
      });
    } finally {
      setLoading(false);
    }
  };

  const startQuiz = (diff: Difficulty) => {
    setDifficulty(diff);
    setCurrentQ(0);
    setScore(0);
    setQuizComplete(false);
    setAnswers([]);
    fetchQuestion(diff);
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null || !question) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    const isCorrect = index === question.correctIndex;
    if (isCorrect) setScore((s) => s + 1);
    setAnswers((a) => [...a, { correct: isCorrect, question: question.question }]);
  };

  const nextQuestion = () => {
    if (currentQ + 1 >= TOTAL_QUESTIONS) {
      setQuizComplete(true);

      // Persist quiz result to localStorage
      try {
        const existing = JSON.parse(localStorage.getItem("matdaan-quiz-results") || "[]");
        existing.push({
          id: `quiz-${Date.now()}`,
          difficulty,
          score: score + (selectedAnswer === question?.correctIndex ? 0 : 0), // score already updated
          total: TOTAL_QUESTIONS,
          takenAt: Date.now(),
        });
        // Keep last 20 results
        if (existing.length > 20) existing.splice(0, existing.length - 20);
        localStorage.setItem("matdaan-quiz-results", JSON.stringify(existing));
      } catch {
        // silently fail
      }
    } else {
      setCurrentQ((q) => q + 1);
      fetchQuestion(difficulty!);
    }
  };

  // Difficulty selection screen
  if (!difficulty) {
    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b border-border px-4 py-3 flex items-center gap-3">
          <Link href="/dashboard" className="p-2 rounded-lg hover:bg-surface transition-colors" aria-label="Back">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div className="flex items-center gap-2">
            <Brain className="w-5 h-5 text-cyan-400" />
            <span className="font-semibold">Election Quiz</span>
          </div>
        </header>

        <main id="main-content" className="flex-1 flex items-center justify-center p-6">
          <div className="max-w-md w-full text-center">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-cyan-500 to-blue-500 flex items-center justify-center mx-auto mb-6">
              <Brain className="w-8 h-8 text-white" />
            </div>
            <h1 className="font-display text-3xl font-bold mb-2">Test Your Knowledge</h1>
            <p className="text-muted-foreground mb-8">
              {TOTAL_QUESTIONS} questions powered by AI. Choose your difficulty level.
            </p>

            <div className="space-y-3">
              {(Object.entries(DIFFICULTY_CONFIG) as [Difficulty, typeof DIFFICULTY_CONFIG[Difficulty]][]).map(
                ([key, config]) => (
                  <button
                    key={key}
                    onClick={() => startQuiz(key)}
                    className="w-full glass glass-hover p-4 flex items-center justify-between group"
                  >
                    <div className="flex items-center gap-3">
                      <config.icon className={`w-5 h-5 ${config.color}`} />
                      <span className="font-medium">{config.label}</span>
                    </div>
                    <ArrowRight className="w-4 h-4 text-muted-foreground group-hover:text-foreground transition-colors" />
                  </button>
                )
              )}
            </div>
          </div>
        </main>
      </div>
    );
  }

  // Quiz complete screen
  if (quizComplete) {
    const percentage = Math.round((score / TOTAL_QUESTIONS) * 100);
    const badge = percentage >= 80 ? "🏆 Election Expert" : percentage >= 50 ? "⭐ Informed Citizen" : "📚 Keep Learning";

    return (
      <div className="min-h-screen flex flex-col">
        <header className="border-b border-border px-4 py-3 flex items-center gap-3">
          <Link href="/dashboard" className="p-2 rounded-lg hover:bg-surface transition-colors" aria-label="Back">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <span className="font-semibold">Quiz Results</span>
        </header>

        <main className="flex-1 flex items-center justify-center p-6">
          <div className="max-w-md w-full text-center">
            <div className="w-20 h-20 rounded-full bg-gradient-to-br from-orange-500 to-amber-400 flex items-center justify-center mx-auto mb-6">
              <Trophy className="w-10 h-10 text-gray-900" />
            </div>

            <h2 className="font-display text-3xl font-bold mb-2">Quiz Complete!</h2>
            <p className="text-4xl font-bold gradient-text mb-2">
              {score}/{TOTAL_QUESTIONS}
            </p>
            <p className="text-muted-foreground mb-2">{percentage}% correct</p>
            <div className="text-lg font-semibold mb-8">{badge}</div>

            {/* Review answers */}
            <div className="glass p-4 mb-6 text-left">
              <h3 className="font-semibold mb-3 text-sm">Review</h3>
              <div className="space-y-2">
                {answers.map((a, i) => (
                  <div key={i} className="flex items-start gap-2 text-sm">
                    {a.correct ? (
                      <CheckCircle className="w-4 h-4 text-green-400 flex-shrink-0 mt-0.5" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                    )}
                    <span className="text-muted-foreground">{a.question}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex gap-3">
              <button onClick={() => setDifficulty(null)} className="btn-secondary flex-1">
                <RotateCcw className="w-4 h-4" />
                Try Again
              </button>
              <Link href="/dashboard" className="btn-primary flex-1 justify-center">
                Dashboard
              </Link>
            </div>
          </div>
        </main>
      </div>
    );
  }

  // Active quiz question
  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b border-border px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Link href="/dashboard" className="p-2 rounded-lg hover:bg-surface transition-colors" aria-label="Back">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <span className="font-semibold text-sm">
            Question {currentQ + 1}/{TOTAL_QUESTIONS}
          </span>
        </div>
        <div className="flex items-center gap-2 text-sm">
          <Sparkles className="w-4 h-4 text-orange-400" />
          <span>Score: {score}</span>
        </div>
      </header>

      {/* Progress bar */}
      <div className="h-1 bg-surface">
        <div
          className="h-full bg-gradient-to-r from-orange-500 to-amber-400 transition-all duration-500"
          style={{ width: `${((currentQ + 1) / TOTAL_QUESTIONS) * 100}%` }}
        />
      </div>

      <main className="flex-1 flex items-center justify-center p-6">
        <div className="max-w-lg w-full">
          {loading ? (
            <div className="text-center">
              <Loader2 className="w-8 h-8 text-orange-400 animate-spin mx-auto mb-4" />
              <p className="text-muted-foreground">Generating question...</p>
            </div>
          ) : question ? (
            <>
              <h2 className="font-display text-xl font-bold mb-6 leading-relaxed">
                {question.question}
              </h2>

              <div className="space-y-3 mb-6">
                {question.options.map((opt, i) => {
                  const isSelected = selectedAnswer === i;
                  const isCorrect = i === question.correctIndex;
                  const showResult = selectedAnswer !== null;

                  let borderClass = "border-border hover:border-orange-500/30";
                  if (showResult && isCorrect) borderClass = "border-green-500 bg-green-500/10";
                  else if (showResult && isSelected && !isCorrect) borderClass = "border-red-500 bg-red-500/10";

                  return (
                    <button
                      key={i}
                      onClick={() => handleAnswer(i)}
                      disabled={selectedAnswer !== null}
                      className={`w-full p-4 rounded-xl border text-left transition-all flex items-center gap-3 ${borderClass} ${
                        !showResult ? "bg-surface" : ""
                      }`}
                    >
                      <div
                        className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold flex-shrink-0 ${
                          showResult && isCorrect
                            ? "bg-green-500 text-white"
                            : showResult && isSelected
                            ? "bg-red-500 text-white"
                            : "bg-surface-hover"
                        }`}
                      >
                        {showResult && isCorrect ? (
                          <CheckCircle className="w-4 h-4" />
                        ) : showResult && isSelected ? (
                          <XCircle className="w-4 h-4" />
                        ) : (
                          String.fromCharCode(65 + i)
                        )}
                      </div>
                      <span className="text-sm">{opt}</span>
                    </button>
                  );
                })}
              </div>

              {/* Explanation */}
              {showExplanation && (
                <div className="glass p-4 mb-6 slide-in-up">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles className="w-4 h-4 text-orange-400" />
                    <span className="font-semibold text-sm">Explanation</span>
                  </div>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    {question.explanation}
                  </p>
                </div>
              )}

              {selectedAnswer !== null && (
                <button onClick={nextQuestion} className="btn-primary w-full justify-center">
                  {currentQ + 1 >= TOTAL_QUESTIONS ? "View Results" : "Next Question"}
                  <ArrowRight className="w-4 h-4" />
                </button>
              )}
            </>
          ) : null}
        </div>
      </main>
    </div>
  );
}

